from flask import Flask, request, make_response

app = Flask(__name__)
@app.route('/help', methods=['POST'])
def help_page():
    help_info = request.form.get('help')

    resp = make_response(f"<h1>Help Center</h1><p>Hello <b>{help_info}</b>!</p>")
    return resp

if __name__ == '__main__':
    app.run()

from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route("/profile")
def profile():
    name = request.args.get("name", "")
    bio = request.args.get("bio", "")
    location = request.args.get("location", "")

    profile = {
        "name": name,
        "bio": bio,
        "location": location
    }

    return jsonify(profile)

if __name__ == "__main__":
    app.run()

from jinja2 import Template

def render_menu(menu):
    template = Template("<h1>Our Menu</h1>{% for item in menu %}<li>{{ item }}</li>{% endfor %}",
                        autoescape=False)
    return template.render(menu=menu.split('\n'))

from jinja2 import Template

def render_cookbook(chef):
    template = Template("{{ chef.name }}'s Cookbook", autoescape=True)
    return template.render(chef=chef)

